// What each JavaScript chunk of the site contains, from its source map (no extra dependency).
// Builds the Pages site with source maps into a scratch folder (unless --dir points at one that has them),
// attributes every generated byte to the source module its mapping names, and prints, per chunk, the raw
// and gzip size, whether the first screen loads it (entry or static import of the entry), and the largest
// modules. --json writes the same numbers for a committed baseline.
//   node tools/bundle-report.mjs [--dir dist-report] [--top 30] [--json docs/bundle-baseline.json] [--no-build]
import { execFileSync } from 'node:child_process';
import { readdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join, relative } from 'node:path';
import { gzipSync } from 'node:zlib';
import { parseArgs } from 'node:util';

const { values } = parseArgs({ options: { dir: { type: 'string', default: 'dist-report' }, top: { type: 'string', default: '30' }, json: { type: 'string' }, 'no-build': { type: 'boolean', default: false } } });
const dir = values.dir, top = Number(values.top);
if (!values['no-build']) {
  execFileSync(process.execPath, ['node_modules/vite/bin/vite.js', 'build', '--sourcemap', '--outDir', dir, '--emptyOutDir', '--logLevel', 'warn'], { stdio: 'inherit' });
}
if (!existsSync(join(dir, '.vite/manifest.json'))) { console.error(`No build with a manifest in ${dir}.`); process.exit(2); }

const BASE64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const digit = new Map([...BASE64].map((c, i) => [c, i]));
/** Decodes one mappings segment ("AAAA") into its numbers. */
function vlq(segment) {
  const out = []; let value = 0, shift = 0;
  for (const c of segment) {
    const d = digit.get(c); value += (d & 31) << shift;
    if (d & 32) shift += 5;
    else { out.push(value & 1 ? -(value >>> 1) : value >>> 1); value = 0; shift = 0; }
  }
  return out;
}
/** Generated bytes per source module (UTF-16 columns, which matches bytes for this ASCII-minified output). */
function attribute(code, map) {
  const lines = code.split('\n'), bytes = new Map(), name = i => i === undefined ? '(unmapped)' : normalise(map.sources[i]);
  let source = 0;
  map.mappings.split(';').forEach((line, row) => {
    const text = lines[row] ?? '', segments = line ? line.split(',').map(vlq) : [];
    let column = 0;
    if (!segments.length) { bytes.set('(unmapped)', (bytes.get('(unmapped)') ?? 0) + text.length + 1); return; }
    const starts = segments.map(s => { column += s[0]; if (s.length > 1) source += s[1]; return { column, source: s.length > 1 ? source : undefined }; });
    if (starts[0].column > 0) bytes.set('(unmapped)', (bytes.get('(unmapped)') ?? 0) + starts[0].column);
    starts.forEach((s, i) => {
      const end = i + 1 < starts.length ? starts[i + 1].column : text.length + 1, key = name(s.source);
      bytes.set(key, (bytes.get(key) ?? 0) + Math.max(0, end - s.column));
    });
  });
  return bytes;
}
function normalise(source) {
  const clean = source.replace(/^(\.\.\/)+/, '').replace(/^\/?/, '');
  const pkg = clean.match(/node_modules\/(?:\.pnpm\/[^/]+\/node_modules\/)?((?:@[^/]+\/)?[^/]+)/);
  return pkg ? `npm:${pkg[1]}` : clean;
}

const manifest = JSON.parse(readFileSync(join(dir, '.vite/manifest.json'), 'utf8'));
const firstScreen = new Set();
(function visit(key) { const item = manifest[key]; if (!item || firstScreen.has(item.file)) return; firstScreen.add(item.file); for (const d of item.imports ?? []) visit(d); })('index.html');

const chunks = [];
for (const file of readdirSync(join(dir, 'assets')).filter(f => f.endsWith('.js'))) {
  const path = join(dir, 'assets', file), code = readFileSync(path, 'utf8');
  const mapPath = path + '.map', map = existsSync(mapPath) ? JSON.parse(readFileSync(mapPath, 'utf8')) : null;
  const modules = map ? attribute(code, map) : new Map([['(no source map)', code.length]]);
  chunks.push({
    file: relative(dir, path), bytes: Buffer.byteLength(code), gzipBytes: gzipSync(code).length, firstScreen: firstScreen.has(`assets/${file}`),
    modules: [...modules].sort((a, b) => b[1] - a[1]).map(([module, bytes]) => ({ module, bytes })),
  });
}
chunks.sort((a, b) => Number(b.firstScreen) - Number(a.firstScreen) || b.bytes - a.bytes);

const kB = n => (n / 1000).toFixed(1) + ' kB';
const first = chunks.filter(c => c.firstScreen);
console.log(`First screen JS: ${kB(first.reduce((n, c) => n + c.bytes, 0))} (${kB(first.reduce((n, c) => n + c.gzipBytes, 0))} gzip) in ${first.length} chunk(s); all JS ${kB(chunks.reduce((n, c) => n + c.bytes, 0))}.`);
for (const chunk of chunks) {
  if (chunk.bytes < 20_000 && !chunk.firstScreen) continue;
  console.log(`\n${chunk.file}  ${kB(chunk.bytes)} (${kB(chunk.gzipBytes)} gzip)${chunk.firstScreen ? '  [first screen]' : ''}`);
  for (const m of chunk.modules.slice(0, top)) console.log(`  ${kB(m.bytes).padStart(10)}  ${m.module}`);
}
const small = chunks.filter(c => c.bytes < 20_000 && !c.firstScreen);
if (small.length) console.log(`\n${small.length} smaller on-demand chunk(s): ${kB(small.reduce((n, c) => n + c.bytes, 0))}.`);
if (values.json) {
  writeFileSync(values.json, JSON.stringify({
    note: 'Generated by tools/bundle-report.mjs: bytes per chunk and its largest source modules (from source maps). firstScreen = entry or a static import of it.',
    chunks: chunks.map(c => ({ ...c, file: c.file.replace(/-[\w-]{8}\.js$/, '.js'), modules: c.modules.slice(0, top) })),
  }, null, 2) + '\n');
  console.log(`\nWrote ${values.json}.`);
}
